const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=n=>'¥'+Number(n||0).toLocaleString('ja-JP');
const initialParams=new URLSearchParams(location.search);
const state={token:localStorage.getItem('ittokai_token')||'',data:null,view:initialParams.get('view')||'home',modal:null,chatUser:null,chatRevision:'',installPrompt:null,documentRevision:0,syncBusy:false,pendingDocumentRefresh:false,syncRevisions:{},deepEntity:initialParams.get('entity')||'',deepConsumed:false};
const CAREDO='https://caredo-zakka.jp/shop/';
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
async function api(path,opt={}){const h={'Content-Type':'application/json',...(opt.headers||{})};if(state.token)h.Authorization='Bearer '+state.token;if(opt.body instanceof FormData)delete h['Content-Type'];const r=await fetch(path,{...opt,headers:h,cache:opt.cache||'no-store'});if(!r.ok){let m='エラー';try{m=(await r.json()).detail||m}catch{}throw new Error(m)}const ct=r.headers.get('content-type')||'';return ct.includes('json')?r.json():r}
async function openProtectedPdf(path,title='ITTOKAI PDF'){
  // /api のPDFはログイン認証が必要。URLを直接開くとAuthorizationヘッダーが付かないため、
  // 現在のセッショントークンで取得してからBlob URLとして表示する。トークンはURLへ露出しない。
  const popup=window.open('about:blank','_blank');
  if(popup){
    try{popup.document.title=title;popup.document.body.innerHTML='<div style="font-family:sans-serif;padding:28px;color:#333">PDFを読み込んでいます…</div>'}catch{}
  }
  try{
    const r=await fetch(path,{headers:{Authorization:'Bearer '+state.token}});
    if(!r.ok){let m='PDFを開けませんでした';try{m=(await r.json()).detail||m}catch{}throw new Error(m)}
    const b=await r.blob();
    const u=URL.createObjectURL(b);
    if(popup){
      popup.location.replace(u);
    }else{
      const a=document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener';document.body.appendChild(a);a.click();a.remove();
    }
    setTimeout(()=>URL.revokeObjectURL(u),5*60*1000);
  }catch(err){
    if(popup)popup.close();
    toast(err.message||'PDFを開けませんでした');
  }
}
function role(){return state.data?.user?.role||''}
function icon(name){const map={home:'⌂',talk:'💬',documents:'✍',requests:'申',visits:'予',procurement:'在',partner:'店',dashboard:'▦',integrations:'⇄',shop:'🛒',me:'●',news:'🔔'};return map[name]||'•'}
const labels={home:'ホーム',talk:'トーク',documents:'書類',requests:'申請',visits:'面会',procurement:'商品・在庫',partner:'店舗・商品',dashboard:'管理',integrations:'連携',shop:'ショップ',me:'マイページ',news:'お知らせ'};
function navItems(){const r=role();if(r==='family')return ['home','talk','documents','shop','me'];if(r==='staff')return ['home','talk','requests','visits','me'];if(r==='middle_manager')return ['home','talk','requests','visits','me'];if(r==='admin')return ['home','dashboard','requests','documents','me'];if(r==='hq')return ['home','dashboard','integrations','me'];if(r==='caredo')return ['home','procurement','me'];if(r==='sponsor')return ['home','partner','me'];return ['home','shop','me']}
function allowedViews(){const r=role();if(r==='family')return ['home','talk','news','documents','visits','shop','me'];if(r==='staff')return ['home','talk','requests','visits','me'];if(r==='middle_manager')return ['home','talk','requests','visits','procurement','me'];if(r==='admin')return ['home','dashboard','talk','news','documents','requests','visits','procurement','me'];if(r==='hq')return ['home','dashboard','integrations','me'];if(r==='caredo')return ['home','procurement','me'];if(r==='sponsor')return ['home','partner','me'];return ['home','shop','me']}
function setView(v){state.view=v;state.modal=null;render();history.replaceState({view:v},'',location.pathname+'?view='+v);if(v==='documents')setTimeout(()=>checkDocumentUpdates(false),0)}
function layout(content){const u=state.data.user,f=state.data.facility;return `<div class="shell"><header class="topbar"><div class="brand"><img src="/assets/ittokai-flight-orange.png"><div><b>ITTOKAI</b><small>${esc(f?.name||u.role_label)}</small></div></div><div class="top-actions"><button class="iconbtn" id="installBtn" title="ホーム画面に追加">＋</button><span class="avatar">${esc(u.name.slice(0,1))}</span></div></header><main class="main">${content}</main><nav class="bottom-nav">${navItems().map(v=>`<button data-view="${v}" class="${state.view===v?'active':''}"><span>${icon(v)}</span><small>${labels[v]}</small></button>`).join('')}</nav></div>${state.modal?modalHtml():''}`}
function loginHtml(){return `<div class="login-wrap"><div class="login-card"><img class="login-logo" src="/assets/ittokai-flight-orange.png"><h1>ITTOKAI</h1><p>人・施設・企業をつなぐ統合業務プラットフォーム</p><form id="loginForm"><label>メールアドレス<input name="email" type="email" value="family@ittokai.local" required></label><label>パスワード<input name="password" type="password" value="demo1234" required></label><button class="primary">ログイン</button></form><details><summary>テスト用アカウント</summary><div class="demo-accounts"><code>family@ittokai.local / demo1234</code><code>staff@ittokai.local / staff1234</code><code>manager@ittokai.local / manager1234</code><code>admin@ittokai.local / admin1234</code><code>hq@ittokai.local / hq1234</code><code>caredo@ittokai.local / caredo1234</code><code>sponsor@ittokai.local / sponsor1234</code></div></details></div></div>`}
function hero(title,sub=''){return `<section class="hero"><div><small>WELCOME</small><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><div class="hero-mark">✦</div></section>`}
function card(title,body='',action=''){return `<section class="card"><div class="card-head"><h3>${title}</h3>${action}</div>${body}</section>`}
