  $('#loginForm')?.addEventListener('submit',async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{const r=await api('/api/login',{method:'POST',body:JSON.stringify(o)});state.token=r.token;state.chatUser=null;state.chatRevision='';localStorage.setItem('ittokai_token',r.token);await load()}catch(err){toast(err.message)}});
  $('#logout')?.addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST'})}catch{}localStorage.removeItem('ittokai_token');state.token='';state.data=null;state.view='home';state.chatUser=null;state.chatRevision='';state.syncRevisions={};render()});
