  $('#lineUnlink')?.addEventListener('click',async()=>{if(!confirm('LINE通知の連携を解除しますか？'))return;await api('/api/line/unlink',{method:'POST'});await load();state.view='me';render();toast('LINE連携を解除しました')});
  $('#retryLineNotifications')?.addEventListener('click',async()=>{try{const r=await api('/api/notifications/retry-failed',{method:'POST'});await load();state.view='dashboard';render();toast(`${r.retried||0}件を再送しました`)}catch(err){toast(err.message)}});
  $$('[data-chat]').forEach(b=>b.onclick=async()=>{try{state.chatUser=Number(b.dataset.chat);const r=await api('/api/messages?user_id='+state.chatUser);state.data.messages=r.messages||[];state.chatRevision=String(r.revision||'');state.view='talk';render();scrollMessages()}catch(err){state.chatUser=null;toast(err.message)}});
  $('[data-chat-back]')?.addEventListener('click',()=>{state.chatUser=null;state.chatRevision='';delete state.data.messages;render()});
  $('#msgForm')?.addEventListener('submit',async e=>{e.preventDefault();const body=e.target.body.value.trim();if(!body)return;try{await api('/api/messages',{method:'POST',body:JSON.stringify({body,user_id:state.chatUser})});e.target.body.value='';const qs=state.chatUser?'?user_id='+state.chatUser:'';const r=await api('/api/messages'+qs);state.data.messages=r.messages||[];state.chatRevision=String(r.revision||'');render();scrollMessages()}catch(err){toast(err.message)}});
  $$('[data-modal]').forEach(b=>b.onclick=()=>{state.modal={type:b.dataset.modal};render()}); $('#modalClose')?.addEventListener('click',async()=>{state.modal=null;render();if(state.pendingDocumentRefresh)await checkActiveUpdates(true)});
  $$('[data-doc]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.doc);try{await api(`/api/documents/${id}/view`,{method:'POST'});await load({renderNow:false})}catch{}state.modal={type:'docDetail',id};render();setupSignature()});
  $$('[data-original]').forEach(b=>b.onclick=()=>openProtectedPdf(`/api/documents/${b.dataset.original}/original`,'ITTOKAI 原本PDF')); $$('[data-pdf]').forEach(b=>b.onclick=()=>openProtectedPdf(`/api/documents/${b.dataset.pdf}/pdf`,'ITTOKAI 署名PDF')); $$('[data-remind]').forEach(b=>b.onclick=async()=>{await api(`/api/documents/${b.dataset.remind}/remind`,{method:'POST'});toast('未署名者へ催促しました')});
  $('#docCreateForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),ids=[...e.target.querySelectorAll('input[name=recipient]:checked')].map(x=>Number(x.value));if(!ids.length)return toast('送付先を選択してください');const file=f.get('file');if(file&&file.size){const fd=new FormData();fd.append('title',f.get('title'));fd.append('category',f.get('category'));fd.append('recipient_user_ids',ids.join(','));if(f.get('resident_id'))fd.append('resident_id',f.get('resident_id'));fd.append('due_days',f.get('due_days'));fd.append('file',file);await api('/api/documents/upload',{method:'POST',body:fd})}else{const o={title:f.get('title'),category:f.get('category'),body:f.get('body'),recipient_user_ids:ids,resident_id:f.get('resident_id')?Number(f.get('resident_id')):null,due_days:Number(f.get('due_days')),requires_signature:true,required_checks:['内容を確認しました','電磁的方法による提供に同意します']};await api('/api/documents',{method:'POST',body:JSON.stringify(o)})}localStorage.setItem('ittokai_doc_revision',String(Date.now()));state.modal=null;await load();state.view='documents';render();toast('書類を送付しました')});
  $('#newsForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);await api('/api/news',{method:'POST',body:JSON.stringify({category:f.get('category'),title:f.get('title'),body:f.get('body'),important:!!f.get('important'),image_url:''})});state.modal=null;await load();state.view='news';render();toast('お知らせを配信しました')});
  $('#signForm')?.addEventListener('submit',async e=>{e.preventDefault();const c=$('#signatureCanvas');if(!c.dataset.drawn)return toast('サインを入力してください');const f=new FormData(e.target);await api(`/api/documents/${f.get('id')}/sign`,{method:'POST',body:JSON.stringify({signer_name:f.get('signer_name'),signature_data:c.toDataURL('image/png'),consent:!!f.get('consent')})});localStorage.setItem('ittokai_doc_revision',String(Date.now()));state.modal=null;await load();state.view='documents';render();toast('署名しました')});
