async function workflowAction(id,action,comment){await api(`/api/workflows/${id}/action`,{method:'POST',body:JSON.stringify({action,comment})});await load();state.view='requests';render();toast('更新しました')}
function setupSignature(){setTimeout(()=>{const c=$('#signatureCanvas');if(!c)return;const ctx=c.getContext('2d');ctx.lineWidth=4;ctx.lineCap='round';ctx.strokeStyle='#172126';let down=false,last=null;const pos=e=>{const r=c.getBoundingClientRect(),t=e.touches?.[0]||e;return [(t.clientX-r.left)*c.width/r.width,(t.clientY-r.top)*c.height/r.height]};const start=e=>{down=true;last=pos(e);e.preventDefault()},move=e=>{if(!down)return;const p=pos(e);ctx.beginPath();ctx.moveTo(...last);ctx.lineTo(...p);ctx.stroke();last=p;c.dataset.drawn='1';e.preventDefault()},end=()=>down=false;c.onpointerdown=start;c.onpointermove=move;c.onpointerup=end;c.onpointerleave=end;$('#clearSign').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);delete c.dataset.drawn}},0)}
function bindSlots(){$$('[data-book]').forEach(b=>b.onclick=async()=>{const x=JSON.parse(b.dataset.book);const representative=prompt('来訪代表者名を入力してください',state.data.user.name);if(!representative)return;const count=Number(prompt('来訪人数',1)||1);await api('/api/visits',{method:'POST',body:JSON.stringify({...x,visitor_count:count,representative,phone:'',notes:''})});await load();state.view='visits';render();toast('面会予約を登録しました')})}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e});
window.addEventListener('popstate',e=>{if(e.state?.view)setView(e.state.view)});
window.addEventListener('focus',()=>{if(state.token)checkActiveUpdates(false)});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.token)checkActiveUpdates(false)});
window.addEventListener('storage',e=>{if(e.key==='ittokai_doc_revision'&&state.token)checkActiveUpdates(false)});
startAutoSync();
window.addEventListener('unhandledrejection',e=>{try{toast(e.reason?.message||'通信エラーが発生しました')}catch{}e.preventDefault()});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js?v=20.7').catch(()=>{});
setTimeout(()=>$('#startup')?.classList.add('hide'),550);
if(state.token)load();else render();
